def containsDuplicate(nums):
    seen = set()
    for x in nums:
        if x in seen:
            return True
        seen.add(x)
    return False

def isAnagram(s, t):
    if len(s) != len(t):
        return False
    count = {}
    for c in s:
        count[c] = count.get(c, 0) + 1
    for c in t:
        if count.get(c, 0) == 0:
            return False
        count[c] -= 1
    return True

def twoSum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

def isValid(s):
    pair = {')': '(', ']': '[', '}': '{'}
    stack = []
    for c in s:
        if c in pair:
            if not stack or stack.pop() != pair[c]:
                return False
        else:
            stack.append(c)
    return not stack

def search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def climbStairs(n):
    a, b = 1, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def majorityElement(nums):
    candidate = nums[0]
    count = 0
    for x in nums:
        if count == 0:
            candidate = x
        count += 1 if x == candidate else -1
    return candidate

def singleNumber(nums):
    result = 0
    for x in nums:
        result ^= x
    return result

def missingNumber(nums):
    n = len(nums)
    result = n
    for i, x in enumerate(nums):
        result ^= i ^ x
    return result

def isPalindrome(s):
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] == '-':
            i += 1
        elif s[j] == '-':
            j -= 1
        else:
            if s[i].lower() != s[j].lower():
                return False
            i += 1
            j -= 1
    return True

def isSubsequence(s, t):
    i = 0
    for c in t:
        if i < len(s) and c == s[i]:
            i += 1
    return i == len(s)

def minCostClimbingStairs(cost):
    prev2, prev1 = cost[0], cost[1]   # best cost of standing on step i-2 and i-1
    for i in range(2, len(cost)):
        prev2, prev1 = prev1, cost[i] + min(prev1, prev2)
    return min(prev1, prev2)

def generate(numRows):
    rows = [[1]]
    for i in range(1, numRows):
        prev = rows[-1]
        row = [1]
        for j in range(1, i):
            row.append(prev[j - 1] + prev[j])
        row.append(1)
        rows.append(row)
    return rows

def plusOne(digits):
    res = list(digits)
    for i in range(len(res) - 1, -1, -1):
        if res[i] < 9:
            res[i] += 1
            return res
        res[i] = 0
    return [1] + res

def mySqrt(x):
    if x < 2:
        return x
    lo, hi = 1, x          # invariant: lo * lo <= x, answer in [lo, hi]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid <= x // mid:
            lo = mid
        else:
            hi = mid - 1
    return lo

def firstUniqChar(s):
    count = {}
    for c in s:
        count[c] = count.get(c, 0) + 1
    for i, c in enumerate(s):
        if count[c] == 1:
            return i
    return -1

def isIsomorphic(s, t):
    if len(s) != len(t):
        return False
    fwd, back = {}, {}
    for a, b in zip(s, t):
        if fwd.setdefault(a, b) != b or back.setdefault(b, a) != a:
            return False
    return True

def longestPalindromeLength(s):
    count = {}
    for c in s:
        count[c] = count.get(c, 0) + 1
    odd = sum(1 for v in count.values() if v % 2 == 1)
    return len(s) - odd + (1 if odd else 0)

def searchInsert(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def moveZeroes(nums):
    write = 0
    for read in range(len(nums)):
        if nums[read] != 0:
            nums[write], nums[read] = nums[read], nums[write]
            write += 1
    return nums

def removeDuplicates(nums):
    if not nums:
        return []
    slow = 0
    for fast in range(1, len(nums)):
        if nums[fast] != nums[slow]:
            slow += 1
            nums[slow] = nums[fast]
    return nums[:slow + 1]

def isHappy(n):
    def nxt(x):
        total = 0
        while x:
            x, d = divmod(x, 10)
            total += d * d
        return total

    slow, fast = n, nxt(n)
    while fast != 1 and slow != fast:
        slow = nxt(slow)
        fast = nxt(nxt(fast))
    return fast == 1

import heapq

def lastStoneWeight(stones):
    heap = [-s for s in stones]
    heapq.heapify(heap)
    while len(heap) > 1:
        y = -heapq.heappop(heap)
        x = -heapq.heappop(heap)
        if y != x:
            heapq.heappush(heap, -(y - x))
    return -heap[0] if heap else 0

def findJudge(n, trust):
    score = [0] * (n + 1)
    for a, b in trust:
        score[a] -= 1
        score[b] += 1
    for p in range(1, n + 1):
        if score[p] == n - 1:
            return p
    return -1

def uniquePaths(m, n):
    row = [1] * n
    for _ in range(1, m):
        for c in range(1, n):
            row[c] += row[c - 1]
    return row[-1]

def findMismatch(nums):
    n = len(nums)
    seen = set()
    dup = 0
    for x in nums:
        if x in seen:
            dup = x
        seen.add(x)
    missing = n * (n + 1) // 2 - sum(nums) + dup
    return [dup, missing]

def intersectWithRepeats(a, b):
    counts = {}
    for x in a:
        counts[x] = counts.get(x, 0) + 1
    out = []
    for x in b:
        if counts.get(x, 0) > 0:
            out.append(x)
            counts[x] -= 1
    out.sort()
    return out

def shortestSameDegree(nums):
    first = {}
    last = {}
    cnt = {}
    for i, x in enumerate(nums):
        if x not in first:
            first[x] = i
        last[x] = i
        cnt[x] = cnt.get(x, 0) + 1
    deg = max(cnt.values())
    return min(last[x] - first[x] + 1 for x in cnt if cnt[x] == deg)

def mergeSortedArrays(a, b):
    out = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

def rangeSums(nums, queries):
    pre = [0]
    for x in nums:
        pre.append(pre[-1] + x)
    return [pre[r + 1] - pre[l] for l, r in queries]

def sortedSquares(nums):
    n = len(nums)
    res = [0] * n
    lo, hi = 0, n - 1
    for pos in range(n - 1, -1, -1):
        if abs(nums[lo]) > abs(nums[hi]):
            res[pos] = nums[lo] * nums[lo]
            lo += 1
        else:
            res[pos] = nums[hi] * nums[hi]
            hi -= 1
    return res

def maxWindowSum(nums, k):
    cur = sum(nums[:k])
    best = cur
    for i in range(k, len(nums)):
        cur += nums[i] - nums[i - k]
        if cur > best:
            best = cur
    return best

def commonElements(a, b):
    i = j = 0
    res = []
    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            i += 1
        elif a[i] > b[j]:
            j += 1
        else:
            res.append(a[i])
            i += 1
            j += 1
    return res

def countNegatives(grid):
    m, n = len(grid), len(grid[0])
    row, col = 0, n - 1
    total = 0
    while row < m and col >= 0:
        if grid[row][col] < 0:
            total += m - row
            col -= 1
        else:
            row += 1
    return total

def stairRows(n):
    lo, hi = 0, 65535
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid * (mid + 1) // 2 <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def minInsertionsToBalance(s):
    open_count = 0   # '(' still waiting for a ')'
    inserted = 0     # '(' we had to add for a ')' with no partner
    for ch in s:
        if ch == '(':
            open_count += 1
        elif open_count > 0:
            open_count -= 1
        else:
            inserted += 1
    return inserted + open_count

def finalPrices(prices):
    answer = list(prices)
    waiting = []   # indices still looking for a discount; their prices never decrease upward
    for i, price in enumerate(prices):
        while waiting and prices[waiting[-1]] >= price:
            answer[waiting.pop()] -= price
        waiting.append(i)
    return answer

def isRotation(s, t):
    if len(s) != len(t):
        return False
    return t in s + s

def romanToInt(s):
    val = {"i": 1, "v": 5, "x": 10, "l": 50, "c": 100, "d": 500, "m": 1000}
    total = 0
    for i, ch in enumerate(s):
        v = val[ch]
        if i + 1 < len(s) and v < val[s[i + 1]]:
            total -= v
        else:
            total += v
    return total

def findFirstOccurrence(haystack, needle):
    m = len(needle)
    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k and needle[i] != needle[k]:
            k = pi[k - 1]
        if needle[i] == needle[k]:
            k += 1
        pi[i] = k
    k = 0
    for i, c in enumerate(haystack):
        while k and c != needle[k]:
            k = pi[k - 1]
        if c == needle[k]:
            k += 1
        if k == m:
            return i - m + 1
    return -1

def countOccurrences(text, pattern):
    m = len(pattern)
    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k and pattern[i] != pattern[k]:
            k = pi[k - 1]
        if pattern[i] == pattern[k]:
            k += 1
        pi[i] = k
    count = 0
    k = 0
    for c in text:
        while k and c != pattern[k]:
            k = pi[k - 1]
        if c == pattern[k]:
            k += 1
        if k == m:
            count += 1
            k = pi[k - 1]
    return count

def repeatingUnitLength(s):
    n = len(s)
    pi = [0] * n
    k = 0
    for i in range(1, n):
        while k and s[i] != s[k]:
            k = pi[k - 1]
        if s[i] == s[k]:
            k += 1
        pi[i] = k
    period = n - pi[-1]
    return period if n % period == 0 else n

def tribonacciMod(n):
    M = 1000000007
    a, b, c = 0, 1, 1
    for _ in range(n):
        a, b, c = b, c, (a + b + c) % M
    return a

def countPathsWithObstacles(grid):
    n = len(grid[0])
    ways = [0] * n
    ways[0] = 1
    for row in grid:
        for c in range(n):
            if row[c] == 1:
                ways[c] = 0
            elif c > 0:
                ways[c] += ways[c - 1]
    return ways[-1]

def minPathSumGrid(grid):
    n = len(grid[0])
    best = [0] * n
    for r, row in enumerate(grid):
        for c in range(n):
            if r == 0 and c == 0:
                best[c] = row[c]
            elif r == 0:
                best[c] = best[c - 1] + row[c]
            elif c == 0:
                best[c] += row[c]
            else:
                best[c] = row[c] + min(best[c], best[c - 1])
    return best[-1]

def zeroOneKnapsack(weights, values, capacity):
    best = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        for c in range(capacity, w - 1, -1):
            cand = best[c - w] + v
            if cand > best[c]:
                best[c] = cand
    return best[capacity]

def unboundedKnapsack(weights, values, capacity):
    best = [0] * (capacity + 1)
    for c in range(1, capacity + 1):
        top = best[c - 1]
        for w, v in zip(weights, values):
            if w <= c and best[c - w] + v > top:
                top = best[c - w] + v
        best[c] = top
    return best[capacity]

def longestCommonSubstring(s, t):
    n = len(t)
    prev = [0] * (n + 1)
    best = 0
    for i in range(1, len(s) + 1):
        cur = [0] * (n + 1)
        c = s[i - 1]
        for j in range(1, n + 1):
            if c == t[j - 1]:
                cur[j] = prev[j - 1] + 1
                if cur[j] > best:
                    best = cur[j]
        prev = cur
    return best

def minDeletionsToEqual(word1, word2):
    m, n = len(word1), len(word2)
    prev = [0] * (n + 1)
    for i in range(1, m + 1):
        cur = [0] * (n + 1)
        a = word1[i - 1]
        for j in range(1, n + 1):
            if a == word2[j - 1]:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = cur[j - 1] if cur[j - 1] > prev[j] else prev[j]
        prev = cur
    return m + n - 2 * prev[n]

def floodFill(image, sr, sc, color):
    res = [row[:] for row in image]
    old = res[sr][sc]
    if old == color:
        return res
    rows, cols = len(res), len(res[0])
    res[sr][sc] = color
    stack = [(sr, sc)]
    while stack:
        y, x = stack.pop()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < rows and 0 <= nx < cols and res[ny][nx] == old:
                res[ny][nx] = color
                stack.append((ny, nx))
    return res

def islandPerimeter(grid):
    land = 0
    shared = 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 1:
                land += 1
                if r > 0 and grid[r - 1][c] == 1:
                    shared += 1
                if c > 0 and grid[r][c - 1] == 1:
                    shared += 1
    return 4 * land - 2 * shared

from collections import deque


def validPath(n, edges, source, destination):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    seen = [False] * n
    seen[source] = True
    q = deque([source])
    while q:
        u = q.popleft()
        if u == destination:
            return True
        for v in adj[u]:
            if not seen[v]:
                seen[v] = True
                q.append(v)
    return False

def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def maxDepth(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    if n == 0:
        return 0
    depth = [1] * n
    best = 1
    for k in range(n):
        for c in (left[k], right[k]):
            if c != -1:
                depth[c] = depth[k] + 1
                best = max(best, depth[c])
    return best

