def isSymmetric(tree):
    vals, left, right = _links(tree)
    if not vals:
        return True
    stack = [(left[0], right[0])]
    while stack:
        a, b = stack.pop()
        if a == -1 and b == -1:
            continue
        if a == -1 or b == -1 or vals[a] != vals[b]:
            return False
        stack.append((left[a], right[b]))
        stack.append((right[a], left[b]))
    return True

def parse(tree):
    # nodes are numbered in the order they appear in the array
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def bstRangeSum(tree, low, high):
    val, left, right = parse(tree)
    total = 0
    stack = [0]
    while stack:
        u = stack.pop()
        x = val[u]
        if low <= x <= high:
            total += x
        if x > low and left[u] != -1:
            stack.append(left[u])
        if x < high and right[u] != -1:
            stack.append(right[u])
    return total

