def mergeTwoLists(a, b):
    l1 = build(a)
    l2 = build(b)
    dummy = ListNode()
    tail = dummy
    while l1 and l2:
        if l2.val < l1.val:
            tail.next = l2
            l2 = l2.next
        else:
            tail.next = l1
            l1 = l1.next
        tail = tail.next
    tail.next = l1 if l1 else l2
    return dump(dummy.next)

