def isPalindromeList(nums):
    head = build(nums)
    slow = fast = head
    while fast.next and fast.next.next:
        slow = slow.next
        fast = fast.next.next
    # reverse everything after slow
    prev = None
    cur = slow.next
    while cur:
        nxt = cur.next
        cur.next = prev
        prev = cur
        cur = nxt
    a, b = head, prev
    while b:
        if a.val != b.val:
            return False
        a = a.next
        b = b.next
    return True

def binaryWatchTimes(turnedOn):
    res = []

    def go(start, left, hours, minutes):
        if hours > 11 or minutes > 59:
            return
        if left == 0:
            res.append(hours * 60 + minutes)
            return
        for led in range(start, 10):
            if led < 4:
                go(led + 1, left - 1, hours | (1 << led), minutes)
            else:
                go(led + 1, left - 1, hours, minutes | (1 << (led - 4)))

    go(0, turnedOn, 0, 0)
    return res

def subsetXorSum(nums):
    acc = 0
    for x in nums:
        acc |= x
    return acc << (len(nums) - 1)

def findContentChildren(g, s):
    g = sorted(g)
    s = sorted(s)
    i = 0
    for size in s:
        if i < len(g) and size >= g[i]:
            i += 1
    return i

