from collections import deque


def orangesRotting(grid):
    rows, cols = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    q = deque()
    fresh = 0
    for r in range(rows):
        for c in range(cols):
            if g[r][c] == 2:
                q.append((r, c))
            elif g[r][c] == 1:
                fresh += 1
    minutes = 0
    while q and fresh:
        for _ in range(len(q)):
            y, x = q.popleft()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < rows and 0 <= nx < cols and g[ny][nx] == 1:
                    g[ny][nx] = 2
                    fresh -= 1
                    q.append((ny, nx))
        minutes += 1
    return -1 if fresh else minutes

import heapq


def networkDelayTime(times, n, k):
    adj = [[] for _ in range(n + 1)]
    for u, v, w in times:
        adj[u].append((v, w))
    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[k] = 0
    heap = [(0, k)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    worst = max(dist[1:])
    return -1 if worst == INF else worst

def countAnagramWindows(s, p):
    n, m = len(s), len(p)
    if m > n:
        return 0
    bal = {}
    for c in p:
        bal[c] = bal.get(c, 0) + 1
    nonzero = len(bal)
    count = 0

    def shift(c, d):
        nonlocal nonzero
        before = bal.get(c, 0)
        after = before + d
        bal[c] = after
        if before == 0 and after != 0:
            nonzero += 1
        elif before != 0 and after == 0:
            nonzero -= 1

    for i in range(n):
        shift(s[i], -1)
        if i >= m:
            shift(s[i - m], 1)
        if i >= m - 1 and nonzero == 0:
            count += 1
    return count

def minDeletionsToOrder(s):
