def minRemovals(nums, x):
    n = len(nums)
    target = sum(nums) - x
    if target < 0:
        return -1
    if target == 0:
        return n
    best = -1
    left = 0
    cur = 0
    for right in range(n):
        cur += nums[right]
        while cur > target:
            cur -= nums[left]
            left += 1
        if cur == target:
            best = max(best, right - left + 1)
    return -1 if best < 0 else n - best

def fourSum(nums, target):
    a = sorted(nums)
    n = len(a)
    res = []
    for i in range(n - 3):
        if i > 0 and a[i] == a[i - 1]:
            continue
        for j in range(i + 1, n - 2):
            if j > i + 1 and a[j] == a[j - 1]:
                continue
            lo, hi = j + 1, n - 1
            while lo < hi:
                s = a[i] + a[j] + a[lo] + a[hi]
                if s < target:
                    lo += 1
                elif s > target:
                    hi -= 1
                else:
                    res.append([a[i], a[j], a[lo], a[hi]])
                    lo += 1
                    hi -= 1
                    while lo < hi and a[lo] == a[lo - 1]:
                        lo += 1
                    while lo < hi and a[hi] == a[hi + 1]:
                        hi -= 1
    return res

def gridContains(grid, target):
    m, n = len(grid), len(grid[0])
    lo, hi = 0, m * n - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        v = grid[mid // n][mid % n]
        if v == target:
            return True
        if v < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

def rotatedContains(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return True
        if nums[lo] == nums[mid] == nums[hi]:
            lo += 1
            hi -= 1
        elif nums[lo] <= nums[mid]:
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return False

def loneValue(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if mid % 2 == 1:
            mid -= 1
        if nums[mid] == nums[mid + 1]:
            lo = mid + 2
        else:
            hi = mid
    return nums[lo]

def earliestDay(bloomDay, m, k):
    n = len(bloomDay)
    if m * k > n:
        return -1

    def bouquets(day):
        made = run = 0
        for b in bloomDay:
            if b <= day:
                run += 1
                if run == k:
                    made += 1
                    run = 0
            else:
                run = 0
        return made

    lo, hi = min(bloomDay), max(bloomDay)
    while lo < hi:
        mid = (lo + hi) // 2
        if bouquets(mid) >= m:
            hi = mid
        else:
            lo = mid + 1
    return lo

def maxMinGap(positions, m):
    pos = sorted(positions)

    def can(d):
        placed, last = 1, pos[0]
        for x in pos[1:]:
            if x - last >= d:
                placed += 1
                last = x
                if placed >= m:
                    return True
        return placed >= m

    lo, hi = 1, (pos[-1] - pos[0]) // (m - 1)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

def kthInGrid(grid, k):
    m, n = len(grid), len(grid[0])

    def count_le(x):
        row, col, total = m - 1, 0, 0
        while row >= 0 and col < n:
            if grid[row][col] > x:
                row -= 1
            else:
                total += row + 1
                col += 1
        return total

    lo, hi = grid[0][0], grid[m - 1][n - 1]
    while lo < hi:
        mid = (lo + hi) // 2
        if count_le(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

def nextGreaterCircular(nums):
    n = len(nums)
    answer = [-1] * n
    waiting = []   # indices with no greater value found yet; values never increase upward
    for k in range(2 * n):
        i = k % n
        while waiting and nums[waiting[-1]] < nums[i]:
            answer[waiting.pop()] = nums[i]
        if k < n:
            waiting.append(i)
    return answer

def removeKDigits(num, k):
    stack = []
    for ch in num:
        while k > 0 and stack and stack[-1] > ch:
            stack.pop()
            k -= 1
        stack.append(ch)
    if k > 0:
        stack = stack[:-k]
    result = "".join(stack).lstrip("0")
    return result if result else "0"

def asteroidCollision(asteroids):
    stack = []
    for a in asteroids:
        alive = True
        while alive and a < 0 and stack and stack[-1] > 0:
            top = stack[-1]
            if top < -a:
                stack.pop()
            elif top == -a:
                stack.pop()
                alive = False
            else:
                alive = False
        if alive:
            stack.append(a)
    return stack

def validateStackSequences(pushed, popped):
    stack = []
    j = 0
    for x in pushed:
        stack.append(x)
        while stack and stack[-1] == popped[j]:
            stack.pop()
            j += 1
    return not stack

def has132Pattern(nums):
    third = None      # largest value known to have a bigger value somewhere to its left
    stack = []        # values scanned so far, decreasing from bottom to top
    for x in reversed(nums):
        if third is not None and x < third:
            return True
        while stack and stack[-1] < x:
            third = stack.pop()
        stack.append(x)
    return False

def intToRoman(num):
    table = [(1000, "m"), (900, "cm"), (500, "d"), (400, "cd"), (100, "c"), (90, "xc"),
             (50, "l"), (40, "xl"), (10, "x"), (9, "ix"), (5, "v"), (4, "iv"), (1, "i")]
    out = []
    for value, sym in table:
        while num >= value:
            out.append(sym)
            num -= value
    return "".join(out)

def multiply(num1, num2):
    a = [ord(c) - 48 for c in reversed(num1)]
    b = [ord(c) - 48 for c in reversed(num2)]
    res = [0] * (len(a) + len(b))
    for i, x in enumerate(a):
        if x == 0:
            continue
        for j, y in enumerate(b):
            res[i + j] += x * y
    carry = 0
    for k in range(len(res)):
        total = res[k] + carry
        res[k] = total % 10
        carry = total // 10
    while len(res) > 1 and res[-1] == 0:
        res.pop()
    return "".join(chr(48 + d) for d in reversed(res))

def convertZigzag(s, numRows):
    if numRows == 1 or numRows >= len(s):
        return s
    rows = [[] for _ in range(numRows)]
    r, step = 0, 1
    for ch in s:
        rows[r].append(ch)
        if r == 0:
            step = 1
        elif r == numRows - 1:
            step = -1
        r += step
    return "".join("".join(row) for row in rows)

from collections import Counter


def longestSubstringAtLeastK(s, k):
    def solve(t):
        if len(t) < k:
            return 0
        cnt = Counter(t)
        bad = {c for c, v in cnt.items() if v < k}
        if not bad:
            return len(t)
        best = 0
        start = 0
        for i, c in enumerate(t):
            if c in bad:
                if i - start >= k:
                    best = max(best, solve(t[start:i]))
                start = i + 1
        if len(t) - start >= k:
            best = max(best, solve(t[start:]))
        return best

    return solve(s)

def longestEvenVowels(s):
    bit = {"a": 1, "e": 2, "i": 4, "o": 8, "u": 16}
    first = {0: 0}
    mask = 0
    best = 0
    for j, ch in enumerate(s, 1):
        mask ^= bit.get(ch, 0)
        if mask in first:
            best = max(best, j - first[mask])
        else:
            first[mask] = j
    return best

def longestBorder(s):
    n = len(s)
    pi = [0] * n
    k = 0
    for i in range(1, n):
        while k and s[i] != s[k]:
            k = pi[k - 1]
        if s[i] == s[k]:
            k += 1
        pi[i] = k
    return pi[-1]

def repeatsToContain(a, b):
    m = len(b)
    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k and b[i] != b[k]:
            k = pi[k - 1]
        if b[i] == b[k]:
            k += 1
        pi[i] = k

    def contains(t):
        k = 0
        for c in t:
            while k and c != b[k]:
                k = pi[k - 1]
            if c == b[k]:
                k += 1
            if k == m:
                return True
        return False

    k0 = -(-m // len(a))
    if contains(a * k0):
        return k0
    if contains(a * (k0 + 1)):
        return k0 + 1
    return -1

def zSum(s):
    n = len(s)
    z = [0] * n
    z[0] = n
    l = r = 0
    for i in range(1, n):
        if i < r:
            z[i] = min(r - i, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l, r = i, i + z[i]
    return sum(z)

def smallestRotation(s):
    n = len(s)
    i, j, k = 0, 1, 0
    while i < n and j < n and k < n:
        a = s[(i + k) % n]
        b = s[(j + k) % n]
        if a == b:
            k += 1
            continue
        if a > b:
            i += k + 1
        else:
            j += k + 1
        if i == j:
            j += 1
        k = 0
    start = min(i, j)
    return s[start:] + s[:start]

def isWildcardMatch(s, p):
    n, m = len(s), len(p)
    i = j = 0
    star = -1
    mark = 0
    while i < n:
        if j < m and (p[j] == '?' or p[j] == s[i]):
            i += 1
            j += 1
        elif j < m and p[j] == '*':
            star = j
            mark = i
            j += 1
        elif star != -1:
            j = star + 1
            mark += 1
            i = mark
        else:
            return False
    while j < m and p[j] == '*':
        j += 1
    return j == m

def robCircle(nums):
    def line(a):
        take, skip = 0, 0
        for x in a:
            take, skip = skip + x, max(take, skip)
        return max(take, skip)

    if len(nums) == 1:
        return nums[0]
    return max(line(nums[:-1]), line(nums[1:]))

def deleteAndEarn(nums):
    top = max(nums)
    gain = [0] * (top + 1)
    for x in nums:
        gain[x] += x
    take, skip = 0, 0
    for v in range(1, top + 1):
        take, skip = skip + gain[v], max(take, skip)
    return max(take, skip)

def countCombinations(amount, coins):
    M = 1000000007
    ways = [0] * (amount + 1)
    ways[0] = 1
    for c in coins:
        for a in range(c, amount + 1):
            ways[a] = (ways[a] + ways[a - c]) % M
    return ways[amount]

def minSquares(n):
    f = [0] + [n] * n
    squares = []
    k = 1
    while k * k <= n:
        squares.append(k * k)
        k += 1
    for m in range(1, n + 1):
        best = m
        for s in squares:
            if s > m:
                break
            if f[m - s] + 1 < best:
                best = f[m - s] + 1
        f[m] = best
    return f[n]

def minCostTickets(days, costs):
    travel = set(days)
    last = days[-1]
    dp = [0] * (last + 1)
    for d in range(1, last + 1):
        if d not in travel:
            dp[d] = dp[d - 1]
        else:
            dp[d] = min(dp[d - 1] + costs[0],
                        dp[max(0, d - 7)] + costs[1],
                        dp[max(0, d - 30)] + costs[2])
    return dp[last]

def countLongestIncreasing(nums):
    M = 1000000007
    n = len(nums)
    length = [1] * n
    count = [1] * n
    for i in range(n):
        x = nums[i]
        li, ci = 1, 1
        for j in range(i):
            if nums[j] < x:
                cand = length[j] + 1
                if cand > li:
                    li, ci = cand, count[j]
                elif cand == li:
                    ci += count[j]
        length[i] = li
        count[i] = ci % M
    best = max(length)
    return sum(count[i] for i in range(n) if length[i] == best) % M

def triangleMinPath(triangle):
    down = triangle[-1][:]
    for i in range(len(triangle) - 2, -1, -1):
        row = triangle[i]
        for j in range(i + 1):
            down[j] = row[j] + min(down[j], down[j + 1])
    return down[0]

def largestSquareOfOnes(matrix):
    n = len(matrix[0])
    prev = [0] * (n + 1)
    best = 0
    for row in matrix:
        cur = [0] * (n + 1)
        for c in range(n):
            if row[c] == 1:
                cur[c + 1] = 1 + min(prev[c], prev[c + 1], cur[c])
                if cur[c + 1] > best:
                    best = cur[c + 1]
        prev = cur
    return best * best

def countAllOnesSquares(matrix):
    n = len(matrix[0])
    prev = [0] * (n + 1)
    total = 0
    for row in matrix:
        cur = [0] * (n + 1)
        for c in range(n):
            if row[c] == 1:
                cur[c + 1] = 1 + min(prev[c], prev[c + 1], cur[c])
                total += cur[c + 1]
        prev = cur
    return total

def countGridExits(m, n, maxMove, startRow, startCol):
    MOD = 10 ** 9 + 7
    ways = [[0] * n for _ in range(m)]
    ways[startRow][startCol] = 1
    out = 0
    for _ in range(maxMove):
        nxt = [[0] * n for _ in range(m)]
        for r in range(m):
            for c in range(n):
                w = ways[r][c]
                if w == 0:
                    continue
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < m and 0 <= nc < n:
                        nxt[nr][nc] = (nxt[nr][nc] + w) % MOD
                    else:
                        out = (out + w) % MOD
        ways = nxt
    return out

def maxItemsTwoBudgets(costA, costB, budgetA, budgetB):
    best = [[0] * (budgetB + 1) for _ in range(budgetA + 1)]
    for x, y in zip(costA, costB):
        for a in range(budgetA, x - 1, -1):
            row = best[a]
            src = best[a - x]
            for b in range(budgetB, y - 1, -1):
                v = src[b - y] + 1
                if v > row[b]:
                    row[b] = v
    return best[budgetA][budgetB]

def countPathsDivisibleByK(grid, k):
    MOD = 10 ** 9 + 7
    n = len(grid[0])
    dp = [[0] * k for _ in range(n)]
    for i, row in enumerate(grid):
        for j in range(n):
            v = row[j] % k
            new = [0] * k
            if i == 0 and j == 0:
                new[v] = 1
            else:
                if i > 0:
                    for rem, cnt in enumerate(dp[j]):
                        if cnt:
                            idx = (rem + v) % k
                            new[idx] = (new[idx] + cnt) % MOD
                if j > 0:
                    for rem, cnt in enumerate(dp[j - 1]):
                        if cnt:
                            idx = (rem + v) % k
                            new[idx] = (new[idx] + cnt) % MOD
            dp[j] = new
    return dp[n - 1][0]

def countSignAssignments(nums, target):
    total = sum(nums)
    if abs(target) > total or (total + target) % 2:
        return 0
    need = (total + target) // 2
    ways = [0] * (need + 1)
    ways[0] = 1
    for x in nums:
        for s in range(need, x - 1, -1):
            ways[s] += ways[s - x]
    return ways[need]

def minRemainingStone(stones):
    total = sum(stones)
    bits = 1
    for s in stones:
        bits |= bits << s
    for a in range(total // 2, -1, -1):
        if (bits >> a) & 1:
            return total - 2 * a
    return total

def countOrderedSums(nums, target):
    MOD = 1_000_000_007
    ways = [0] * (target + 1)
    ways[0] = 1
    for t in range(1, target + 1):
        total = 0
        for x in nums:
            if x <= t:
                total += ways[t - x]
        ways[t] = total % MOD
    return ways[target]

def minScoreTriangulation(values):
    n = len(values)
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n):
        for i in range(n - length):
            j = i + length
            best = None
            for k in range(i + 1, j):
                cost = dp[i][k] + dp[k][j] + values[i] * values[k] * values[j]
                if best is None or cost < best:
                    best = cost
            dp[i][j] = best
    return dp[0][n - 1]

def canFirstPlayerWin(maxChoosable, desiredTotal):
    if desiredTotal <= 0:
        return True
    if maxChoosable * (maxChoosable + 1) // 2 < desiredTotal:
        return False
    memo = {}

    def win(used, remaining):
        if used in memo:
            return memo[used]
        result = False
        for i in range(maxChoosable):
            bit = 1 << i
            if used & bit:
                continue
            if i + 1 >= remaining or not win(used | bit, remaining - (i + 1)):
                result = True
                break
        memo[used] = result
        return result

    return win(0, desiredTotal)

def canFirstPlayerWinPiles(nums):
    n = len(nums)
    dp = nums[:]          # dp[j] = diff(i, j) for the current i
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            dp[j] = max(nums[i] - dp[j], nums[j] - dp[j - 1])
    return dp[n - 1] >= 0

def longestPalindromeSubseq(s):
    n = len(s)
    if n == 0:
        return 0
    dp = [0] * n
    for i in range(n - 1, -1, -1):
        dp[i] = 1
        diag = 0                      # value of P(i+1, j-1) for the current j
        for j in range(i + 1, n):
            keep = dp[j]              # P(i+1, j); becomes the diagonal for j+1
            if s[i] == s[j]:
                dp[j] = diag + 2
            else:
                dp[j] = keep if keep > dp[j - 1] else dp[j - 1]
            diag = keep
    return dp[n - 1]

def minimumDeleteSum(s1, s2):
    m, n = len(s1), len(s2)
    prev = [0] * (n + 1)
    for i in range(1, m + 1):
        cur = [0] * (n + 1)
        a = s1[i - 1]
        w = ord(a)
        for j in range(1, n + 1):
            if a == s2[j - 1]:
                cur[j] = prev[j - 1] + w
            else:
                cur[j] = cur[j - 1] if cur[j - 1] > prev[j] else prev[j]
        prev = cur
    total = sum(map(ord, s1)) + sum(map(ord, s2))
    return total - 2 * prev[n]

def isInterleave(s1, s2, s3):
    m, n = len(s1), len(s2)
    if m + n != len(s3):
        return False
    dp = [False] * (n + 1)
    dp[0] = True
    for j in range(1, n + 1):
        dp[j] = dp[j - 1] and s2[j - 1] == s3[j - 1]
    for i in range(1, m + 1):
        dp[0] = dp[0] and s1[i - 1] == s3[i - 1]
        for j in range(1, n + 1):
            c = s3[i + j - 1]
            dp[j] = (dp[j] and s1[i - 1] == c) or (dp[j - 1] and s2[j - 1] == c)
    return dp[n]

def isWildcardMatch(s, p):
    i = j = 0
    m, n = len(s), len(p)
    star = -1          # index of the latest '*' in p
    mark = 0           # index in s where that star started absorbing
    while i < m:
        if j < n and (p[j] == '?' or p[j] == s[i]):
            i += 1
            j += 1
        elif j < n and p[j] == '*':
            star = j
            mark = i
            j += 1
        elif star != -1:
            j = star + 1
            mark += 1
            i = mark
        else:
            return False
    while j < n and p[j] == '*':
        j += 1
    return j == n

def longestRepeatingSubsequence(s):
    n = len(s)
    prev = [0] * (n + 1)
    for i in range(1, n + 1):
        cur = [0] * (n + 1)
        c = s[i - 1]
        for j in range(1, n + 1):
            if c == s[j - 1] and i != j:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = cur[j - 1] if cur[j - 1] > prev[j] else prev[j]
        prev = cur
    return prev[n]

def lcsOfThree(a, b, c):
    nb, nc = len(b), len(c)
    prev = [[0] * (nc + 1) for _ in range(nb + 1)]
    for i in range(1, len(a) + 1):
        cur = [[0] * (nc + 1) for _ in range(nb + 1)]
        x = a[i - 1]
        for j in range(1, nb + 1):
            y = b[j - 1]
            row, prow, crow = cur[j], prev[j], cur[j - 1]
            pdiag = prev[j - 1]
            for k in range(1, nc + 1):
                if x == y == c[k - 1]:
                    row[k] = pdiag[k - 1] + 1
                else:
                    best = prow[k]
                    if crow[k] > best:
                        best = crow[k]
                    if row[k - 1] > best:
                        best = row[k - 1]
                    row[k] = best
        prev = cur
    return prev[nb][nc]

def captureRegions(board):
    rows, cols = len(board), len(board[0])
    safe = [[False] * cols for _ in range(rows)]
    stack = []
    for r in range(rows):
        for c in range(cols):
            if (r in (0, rows - 1) or c in (0, cols - 1)) and board[r][c] == 0:
                safe[r][c] = True
                stack.append((r, c))
    while stack:
        y, x = stack.pop()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < rows and 0 <= nx < cols and board[ny][nx] == 0 and not safe[ny][nx]:
                safe[ny][nx] = True
                stack.append((ny, nx))
    return [[0 if safe[r][c] else 1 for c in range(cols)] for r in range(rows)]

def countDistinctShapes(grid):
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    shapes = set()
    for r0 in range(rows):
        for c0 in range(cols):
            if grid[r0][c0] == 1 and not seen[r0][c0]:
                seen[r0][c0] = True
                stack = [(r0, c0)]
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y - r0, x - c0))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < rows and 0 <= nx < cols and grid[ny][nx] == 1 and not seen[ny][nx]:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
