def combine(n, k):
    res = []
    cur = []

    def go(start):
        if len(cur) == k:
            res.append(cur[:])
            return
        for v in range(start, n - (k - len(cur)) + 2):
            cur.append(v)
            go(v + 1)
            cur.pop()

    go(1)
    return res

def wordPathExists(board, word):
    m, n = len(board), len(board[0])
    codes = [ord(ch) - 96 for ch in word]
    L = len(codes)
    have = {}
    for row in board:
        for x in row:
            have[x] = have.get(x, 0) + 1
    need = {}
    for x in codes:
        need[x] = need.get(x, 0) + 1
    for x, v in need.items():
        if have.get(x, 0) < v:
            return False
    if have.get(codes[0], 0) > have.get(codes[-1], 0):
        codes.reverse()
    seen = [[False] * n for _ in range(m)]

    def go(r, c, k):
        if board[r][c] != codes[k]:
            return False
        if k == L - 1:
            return True
        seen[r][c] = True
        found = False
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and not seen[nr][nc] and go(nr, nc, k + 1):
                found = True
                break
        seen[r][c] = False
        return found

    for r in range(m):
        for c in range(n):
            if go(r, c, 0):
                return True
    return False

def countArrangements(n):
    memo = {}

    def go(used, pos):
        # pos counts down from n to 1; used is the bitmask of values already placed
        if pos == 0:
            return 1
        if used in memo:
            return memo[used]
        total = 0
        for v in range(1, n + 1):
            if not used >> (v - 1) & 1 and (v % pos == 0 or pos % v == 0):
                total += go(used | (1 << (v - 1)), pos - 1)
        memo[used] = total
        return total

    return go(0, n)

