        i += 1
    return sum(sieve)

def powerMod(base, exp, mod):
    result = 1 % mod
    cur = base % mod
    while exp > 0:
        if exp & 1:
            result = result * cur % mod
        cur = cur * cur % mod
        exp >>= 1
    return result

def superPow(a, b):
    MOD = 1337

    def pw(x, k):
        r = 1
        while k:
            if k & 1:
                r = r * x % MOD
            x = x * x % MOD
            k >>= 1
        return r

    a %= MOD
    result = 1
    for d in b:
        result = pw(result, 10) * pw(a, d) % MOD
    return result

def singleNumberTriple(nums):
