            cols[c].add(d)
            boxes[b].add(d)
    return True

def trap(height):
    lo, hi = 0, len(height) - 1
    left = right = water = 0
    while lo < hi:
        if height[lo] < height[hi]:
            left = max(left, height[lo])
            water += left - height[lo]
            lo += 1
        else:
            right = max(right, height[hi])
            water += right - height[hi]
            hi -= 1
    return water

from collections import deque

def maxSlidingWindow(nums, k):
    dq = deque()
    out = []
    for i, x in enumerate(nums):
        while dq and nums[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            out.append(nums[dq[0]])
    return out

def minWindow(s, t):
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1
    missing = len(t)
    best_start, best_len = 0, len(s) + 1
    left = 0
    for right, c in enumerate(s):
        if need.get(c, 0) > 0:
            missing -= 1
        need[c] = need.get(c, 0) - 1
        while missing == 0:
            if right - left + 1 < best_len:
                best_start, best_len = left, right - left + 1
            need[s[left]] += 1
            if need[s[left]] > 0:
                missing += 1
            left += 1
    return "" if best_len > len(s) else s[best_start:best_start + best_len]

def minDistance(word1, word2):
    n, m = len(word1), len(word2)
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        for j in range(1, m + 1):
            if word1[i - 1] == word2[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j - 1], prev[j], cur[j - 1])
        prev = cur
    return prev[m]

def totalNQueens(n):
    cols, d1, d2 = set(), set(), set()

    def place(r):
        if r == n:
            return 1
        total = 0
        for c in range(n):
            if c in cols or (r - c) in d1 or (r + c) in d2:
                continue
            cols.add(c)
            d1.add(r - c)
            d2.add(r + c)
            total += place(r + 1)
            cols.remove(c)
            d1.remove(r - c)
            d2.remove(r + c)
        return total

    return place(0)

def findLowerMedian(a, b):
    if len(a) > len(b):
        a, b = b, a
    m, n = len(a), len(b)
    L = (m + n - 1) // 2 + 1          # how many of the smallest elements form the left part
    lo, hi = max(0, L - n), min(m, L)  # i = how many of them come from a
    while lo < hi:
        i = (lo + hi) // 2
        j = L - i
        if a[i] < b[j - 1]:
            lo = i + 1
        else:
            hi = i
    i = lo
    j = L - i
    best = None
    if i > 0:
        best = a[i - 1]
    if j > 0 and (best is None or b[j - 1] > best):
        best = b[j - 1]
    return best

def firstMissingPositive(nums):
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            j = nums[i] - 1
            nums[i], nums[j] = nums[j], nums[i]
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n + 1

def longestValidParentheses(s):
    stack = [-1]
    best = 0
    for i, c in enumerate(s):
        if c == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                best = max(best, i - stack[-1])
    return best

def maxCoins(nums):
    a = [1] + list(nums) + [1]
    m = len(a)
    dp = [[0] * m for _ in range(m)]
    for gap in range(2, m):
        for l in range(m - gap):
            r = l + gap
            lr = a[l] * a[r]
            best = 0
            for k in range(l + 1, r):
                v = dp[l][k] + dp[k][r] + lr * a[k]
                if v > best:
                    best = v
            dp[l][r] = best
    return dp[0][m - 1]

def isMatch(s, p):
    m, n = len(s), len(p)
    nxt = [False] * (n + 1)          # row i + 1; start with i = m (empty rest of text)
    nxt[n] = True
    for j in range(n - 2, -1, -1):
        nxt[j] = p[j + 1] == '*' and nxt[j + 2]
    # nxt now describes i = m
    for i in range(m - 1, -1, -1):
        cur = [False] * (n + 1)
        for j in range(n - 1, -1, -1):
            first = p[j] == s[i] or p[j] == '.'
            if j + 1 < n and p[j + 1] == '*':
                cur[j] = cur[j + 2] or (first and nxt[j])
            else:
                cur[j] = first and nxt[j + 1]
        nxt = cur
    return nxt[0]

def canPartitionKSubsets(nums, k):
    total = sum(nums)
    if total % k:
        return False
    target = total // k
    a = sorted(nums)
    if a[-1] > target:
        return False
    n = len(a)
    full = (1 << n) - 1
    dead = set()

    def go(mask, cur):
        if mask == full:
            return True
        if mask in dead:
            return False
        for i in range(n):
            if mask >> i & 1:
                continue
            if cur + a[i] > target:
                break
            if i and a[i] == a[i - 1] and not (mask >> (i - 1) & 1):
                continue
            nxt = cur + a[i]
            if go(mask | (1 << i), 0 if nxt == target else nxt):
                return True
        dead.add(mask)
        return False

    return go(0, 0)

def longestIncreasingPath(matrix):
    rows, cols = len(matrix), len(matrix[0])
    order = sorted((matrix[r][c], r, c) for r in range(rows) for c in range(cols))
    length = [[1] * cols for _ in range(rows)]
    best = 1
    for v, r, c in order:
        m = 0
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and matrix[nr][nc] < v and length[nr][nc] > m:
                m = length[nr][nc]
        length[r][c] = m + 1
        if length[r][c] > best:
            best = length[r][c]
    return best

def numDistinct(s, t):
    m = len(t)
    dp = [0] * (m + 1)
    dp[0] = 1
    for c in s:
        for j in range(m, 0, -1):
            if t[j - 1] == c:
                dp[j] += dp[j - 1]
    return dp[m]

def shortestPalindromeLength(s):
    n = len(s)
    t = s + '#' + s[::-1]
    pi = [0] * len(t)
    for i in range(1, len(t)):
        k = pi[i - 1]
        while k and t[i] != t[k]:
            k = pi[k - 1]
        if t[i] == t[k]:
            k += 1
        pi[i] = k
    return 2 * n - pi[-1]

def splitArray(nums, k):
    def pieces(limit):
        count, cur = 1, 0
        for x in nums:
            if cur + x > limit:
                count += 1
                cur = 0
            cur += x
        return count

    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if pieces(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

def shortestSubarray(nums, k):
    from collections import deque
    n = len(nums)
    pre = [0] * (n + 1)
    for i, x in enumerate(nums):
        pre[i + 1] = pre[i] + x
    best = n + 1
    dq = deque()
    for j in range(n + 1):
        while dq and pre[j] - pre[dq[0]] >= k:
            best = min(best, j - dq.popleft())
        while dq and pre[dq[-1]] >= pre[j]:
            dq.pop()
        dq.append(j)
    return best if best <= n else -1

def candy(ratings):
    n = len(ratings)
    give = [1] * n
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            give[i] = give[i - 1] + 1
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1] and give[i] <= give[i + 1]:
            give[i] = give[i + 1] + 1
    return sum(give)

def numIslands2(m, n, positions):
    parent = list(range(m * n))
    size = [1] * (m * n)
    land = [False] * (m * n)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    count = 0
    out = []
    for r, c in positions:
        idx = r * n + c
        if not land[idx]:
            land[idx] = True
            count += 1
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and land[nr * n + nc]:
                    a, b = find(idx), find(nr * n + nc)
                    if a != b:
                        if size[a] < size[b]:
                            a, b = b, a
                        parent[b] = a
                        size[a] += size[b]
                        count -= 1
        out.append(count)
    return out

def minCut(s):
    n = len(s)
    cuts = [i - 1 for i in range(n + 1)]
    for c in range(n):
        for l, r in ((c, c), (c, c + 1)):
            while l >= 0 and r < n and s[l] == s[r]:
                if cuts[l] + 1 < cuts[r + 1]:
                    cuts[r + 1] = cuts[l] + 1
                l -= 1
                r += 1
    return cuts[n]

def countExactlyKDistinct(nums, k):
    def at_most(m):
        if m == 0:
            return 0
        freq = {}
        left = 0
        total = 0
        for right, x in enumerate(nums):
            freq[x] = freq.get(x, 0) + 1
            while len(freq) > m:
                y = nums[left]
                freq[y] -= 1
                if freq[y] == 0:
                    del freq[y]
                left += 1
            total += right - left + 1
        return total
    return at_most(k) - at_most(k - 1)

def countEqualThree(nums):
    seen = {(0, 0): 1}
    c = [0, 0, 0]
    total = 0
    for x in nums:
        c[x] += 1
        key = (c[1] - c[0], c[2] - c[1])
        total += seen.get(key, 0)
        seen[key] = seen.get(key, 0) + 1
    return total

def maxOverlapAfterEach(bookings):
    xs = sorted({x for b in bookings for x in b})
    rank = {x: i for i, x in enumerate(xs)}
    m = len(xs) - 1  # elementary cells between consecutive endpoints
    mx = [0] * (4 * m)
    add_ = [0] * (4 * m)

    def update(node, l, r, a, b):
        if a <= l and r <= b:
            mx[node] += 1
            add_[node] += 1
            return
        mid = (l + r) // 2
        if a <= mid:
            update(2 * node, l, mid, a, b)
        if b > mid:
            update(2 * node + 1, mid + 1, r, a, b)
        mx[node] = add_[node] + max(mx[2 * node], mx[2 * node + 1])

    out = []
    for s, e in bookings:
        update(1, 0, m - 1, rank[s], rank[e] - 1)
        out.append(mx[1])
    return out

def shortestWindowLength(nums, pattern):
    n, m = len(nums), len(pattern)
    best = -1
    i = 0
    while i < n:
        j = 0
        k = i
        while k < n and j < m:
            if nums[k] == pattern[j]:
                j += 1
            k += 1
        if j < m:
            break
        end = k - 1
        j = m - 1
        k = end
        while j >= 0:
            if nums[k] == pattern[j]:
                j -= 1
            k -= 1
        start = k + 1
        length = end - start + 1
        if best < 0 or length < best:
            best = length
        i = start + 1
    return best

def minKWindowFlips(nums, k):
    n = len(nums)
    end = [0] * (n + 1)
    parity = 0
    flips = 0
    for i in range(n):
        parity ^= end[i]
        if nums[i] ^ parity == 0:
            if i + k > n:
                return -1
            flips += 1
            parity ^= 1
            end[i + k] ^= 1
    return flips

def kthPairGap(nums, k):
    a = sorted(nums)
    n = len(a)

    def pairs_within(d):
        total = left = 0
        for right in range(n):
            while a[right] - a[left] > d:
                left += 1
            total += right - left
        return total

    lo, hi = 0, a[-1] - a[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if pairs_within(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

def minLargestGap(stations, k):
    n = len(stations)
    if n == 1:
        return 0
    gaps = [stations[i + 1] - stations[i] for i in range(n - 1)]

    def need(d):
        return sum((g - 1) // d for g in gaps)

    lo, hi = 1, max(gaps)
    while lo < hi:
        mid = (lo + hi) // 2
        if need(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

def maximalRectangle(matrix):
    cols = len(matrix[0])
    heights = [0] * (cols + 1)   # last slot is a 0 sentinel that flushes the stack
    best = 0
    for row in matrix:
        for c in range(cols):
            heights[c] = heights[c] + 1 if row[c] == 1 else 0
        stack = [-1]
        for c in range(cols + 1):
            while stack[-1] != -1 and heights[stack[-1]] >= heights[c]:
                h = heights[stack.pop()]
                best = max(best, h * (c - stack[-1] - 1))
            stack.append(c)
    return best

def minWindowSubsequence(s, t):
    m = len(t)
    where = {}
    for j, c in enumerate(t, 1):
        where.setdefault(c, []).append(j)
    for c in where:
        where[c].reverse()  # descending j
    start = [-1] * (m + 1)
    best = 0
    for i, ch in enumerate(s):
        for j in where.get(ch, ()):
            if j == 1:
                start[1] = i
            elif start[j - 1] != -1:
                start[j] = start[j - 1]
            if j == m and start[m] != -1:
                length = i - start[m] + 1
                if best == 0 or length < best:
                    best = length
    return best

def longestDuplicateLength(s):
    n = len(s)
    MOD = (1 << 61) - 1
    BASE = 911382323
    vals = [ord(c) for c in s]

    def has_dup(L):
        h = 0
        for i in range(L):
            h = (h * BASE + vals[i]) % MOD
        top = pow(BASE, L - 1, MOD)
        seen = {h: [0]}
        for i in range(1, n - L + 1):
            h = ((h - vals[i - 1] * top) * BASE + vals[i + L - 1]) % MOD
            if h in seen:
                sub = s[i:i + L]
                for j in seen[h]:
                    if s[j:j + L] == sub:
                        return True
                seen[h].append(i)
            else:
                seen[h] = [i]
        return False

    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if has_dup(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

def maxProfitK(k, prices):
    n = len(prices)
    if k == 0 or n < 2:
        return 0
    if k >= n // 2:
        return sum(max(0, prices[i] - prices[i - 1]) for i in range(1, n))
    NEG = -10 ** 9
    buy = [NEG] * (k + 1)
    sell = [0] * (k + 1)
    for p in prices:
        for j in range(1, k + 1):
            if sell[j - 1] - p > buy[j]:
                buy[j] = sell[j - 1] - p
            if buy[j] + p > sell[j]:
                sell[j] = buy[j] + p
    return sell[k]

def maxSumThreeWindows(nums, k):
    n = len(nums)
    m = n - k + 1                     # number of window starts
    w = [0] * m
    s = sum(nums[:k])
    w[0] = s
    for i in range(1, m):
        s += nums[i + k - 1] - nums[i - 1]
        w[i] = s
    left = w[:]
    for i in range(1, m):
        if left[i - 1] > left[i]:
            left[i] = left[i - 1]
    right = w[:]
    for i in range(m - 2, -1, -1):
        if right[i + 1] > right[i]:
            right[i] = right[i + 1]
    best = 0
    for b in range(k, m - k):
        total = left[b - k] + w[b] + right[b + k]
        if total > best:
            best = total
    return best

def minStartingHealth(dungeon):
    m, n = len(dungeon), len(dungeon[0])
    INF = float("inf")
    need = [INF] * (n + 1)
    need[n - 1] = 1
    for r in range(m - 1, -1, -1):
        for c in range(n - 1, -1, -1):
            nxt = min(need[c], need[c + 1])
            need[c] = max(1, nxt - dungeon[r][c])
    return need[0]

def twoRobotsCherries(grid):
    rows, cols = len(grid), len(grid[0])
    NEG = float("-inf")
    last = grid[-1]
    f = [[(last[a] + (last[b] if a != b else 0)) for b in range(cols)] for a in range(cols)]
    for r in range(rows - 2, -1, -1):
        row = grid[r]
        g = [[NEG] * cols for _ in range(cols)]
        for a in range(cols):
            alo, ahi = max(0, a - 1), min(cols - 1, a + 1)
            for b in range(cols):
                blo, bhi = max(0, b - 1), min(cols - 1, b + 1)
                best = NEG
                for na in range(alo, ahi + 1):
                    fa = f[na]
                    for nb in range(blo, bhi + 1):
                        if fa[nb] > best:
                            best = fa[nb]
                g[a][b] = best + row[a] + (row[b] if a != b else 0)
        f = g
    return f[0][cols - 1]

def mergeStonesMinCost(stones, k):
    n = len(stones)
    if (n - 1) % (k - 1):
        return -1
    pre = [0]
    for s in stones:
        pre.append(pre[-1] + s)
    dp = [[0] * n for _ in range(n)]
    for length in range(k, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            best = min(dp[i][m] + dp[m + 1][j] for m in range(i, j, k - 1))
            if (length - 1) % (k - 1) == 0:
                best += pre[j + 1] - pre[i]
            dp[i][j] = best
    return dp[0][n - 1]

from collections import deque


def shortestWalkAllNodes(graph):
    n = len(graph)
    full = (1 << n) - 1
    if n == 1:
        return 0
    seen = [[False] * n for _ in range(1 << n)]
    dq = deque()
    for i in range(n):
        seen[1 << i][i] = True
        dq.append((1 << i, i, 0))
    while dq:
        mask, u, d = dq.popleft()
        for v in graph[u]:
            nm = mask | (1 << v)
            if nm == full:
                return d + 1
            if not seen[nm][v]:
                seen[nm][v] = True
                dq.append((nm, v, d + 1))
    return -1

def countPalindromicSubsequences(s):
    MOD = 10 ** 9 + 7
    n = len(s)
    prv = [-1] * n      # previous index with the same letter
    nxt = [n] * n       # next index with the same letter
    last = {}
    for i in range(n):
        prv[i] = last.get(s[i], -1)
        last[s[i]] = i
    last = {}
    for i in range(n - 1, -1, -1):
        nxt[i] = last.get(s[i], n)
        last[s[i]] = i
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            inner = dp[i + 1][j - 1]
            if s[i] != s[j]:
                v = dp[i + 1][j] + dp[i][j - 1] - inner
            else:
                l, r = nxt[i], prv[j]
                if l > r:
                    v = 2 * inner + 2
                elif l == r:
                    v = 2 * inner + 1
                else:
                    v = 2 * inner - dp[l + 1][r - 1]
            dp[i][j] = v % MOD
    return dp[0][n - 1]

def isScramble(s1, s2):
    n = len(s1)
    if n != len(s2):
        return False
    memo = {}

    def go(i, j, L):
        key = (i, j, L)
        if key in memo:
            return memo[key]
        a = s1[i:i + L]
        b = s2[j:j + L]
        if a == b:
            res = True
        elif sorted(a) != sorted(b):
            res = False
        else:
            res = False
            for k in range(1, L):
                if go(i, j, k) and go(i + k, j + k, L - k):
                    res = True
                    break
                if go(i, j + L - k, k) and go(i + k, j, L - k):
                    res = True
                    break
        memo[key] = res
        return res

    return go(0, 0, n)

from collections import deque


def minRemovals(grid):
    rows, cols = len(grid), len(grid[0])
    BIG = 10 ** 9
    dist = [[BIG] * cols for _ in range(rows)]
    dist[0][0] = 0
    dq = deque([(0, 0)])
    while dq:
        y, x = dq.popleft()
        d = dist[y][x]
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < rows and 0 <= nx < cols:
                nd = d + grid[ny][nx]
                if nd < dist[ny][nx]:
                    dist[ny][nx] = nd
                    if grid[ny][nx] == 0:
                        dq.appendleft((ny, nx))
                    else:
                        dq.append((ny, nx))
    return dist[rows - 1][cols - 1]

import heapq


def swimInWater(elevation):
    n = len(elevation)
    seen = [[False] * n for _ in range(n)]
    heap = [(elevation[0][0], 0, 0)]
    seen[0][0] = True
    while heap:
        t, y, x = heapq.heappop(heap)
        if y == n - 1 and x == n - 1:
            return t
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < n and 0 <= nx < n and not seen[ny][nx]:
                seen[ny][nx] = True
                heapq.heappush(heap, (max(t, elevation[ny][nx]), ny, nx))
    return -1

