def alienOrder(m, words):
    adj = [set() for _ in range(m)]
    indeg = [0] * m
    for a, b in zip(words, words[1:]):
        k = 0
        lim = min(len(a), len(b))
        while k < lim and a[k] == b[k]:
            k += 1
        if k == lim:
            if len(a) > len(b):
                return []
            continue
        if b[k] not in adj[a[k]]:
            adj[a[k]].add(b[k])
            indeg[b[k]] += 1
    heap = [c for c in range(m) if indeg[c] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        c = heapq.heappop(heap)
        order.append(c)
        for d in adj[c]:
            indeg[d] -= 1
            if indeg[d] == 0:
                heapq.heappush(heap, d)
    return order if len(order) == m else []

def classifyMstEdges(n, edges):
    E = len(edges)
    order = sorted(range(E), key=lambda i: edges[i][2])
    INF = float('inf')

    def kruskal(skip, force):
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        total = 0
        used = 0
        if force >= 0:
            a, b, w = edges[force]
            parent[find(a)] = find(b)
            total += w
            used += 1
        for i in order:
            if i == skip or i == force:
                continue
            a, b, w = edges[i]
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                total += w
                used += 1
        return total if used == n - 1 else INF

    best = kruskal(-1, -1)
    res = []
    for i in range(E):
        if kruskal(i, -1) > best:
            res.append(2)
        elif kruskal(-1, i) == best:
            res.append(1)
        else:
            res.append(0)
    return res

def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def minCameras(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    if n == 0:
        return 0
    # 0 = not watched, 1 = holds a camera, 2 = watched by a child's camera
    state = [0] * n
    cameras = 0
    for k in range(n - 1, -1, -1):
        kids = [state[c] for c in (left[k], right[k]) if c != -1]
        if 0 in kids:
            state[k] = 1
            cameras += 1
        elif 1 in kids:
            state[k] = 2
        else:
            state[k] = 0
    return cameras + (1 if state[0] == 0 else 0)

