def maxBstSubtreeSum(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    ok = [False] * n
    lo = [0] * n
    hi = [0] * n
    total = [0] * n
    best = 0
    for k in range(n - 1, -1, -1):
        v = vals[k]
        good = True
        mn = mx = v
        s = v
        l, r = left[k], right[k]
        if l != -1:
            if ok[l] and hi[l] < v:
                mn = lo[l]
                s += total[l]
            else:
                good = False
        if r != -1:
            if ok[r] and lo[r] > v:
                mx = hi[r]
                s += total[r]
            else:
                good = False
        ok[k], lo[k], hi[k], total[k] = good, mn, mx, s
        if good and s > best:
            best = s
    return best

def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def minCameraCover(tree):
    val, left, right = parse(tree)
    n = len(val)
    # 0 = not watched, 1 = watched, no camera, 2 = camera
    state = [0] * n
    cameras = 0
    for u in range(n - 1, -1, -1):
        kids = [state[c] for c in (left[u], right[u]) if c != -1]
        if 0 in kids:
            state[u] = 2
            cameras += 1
        elif 2 in kids:
            state[u] = 1
    if state[0] == 0:
        cameras += 1
    return cameras

def countSameBstReorders(nums):
    MOD = 10 ** 9 + 7
    n = len(nums)
    left = [-1] * n
    right = [-1] * n
    for i in range(1, n):
        x = nums[i]
        u = 0
        while True:
            kids = left if x < nums[u] else right
            if kids[u] == -1:
                kids[u] = i
                break
            u = kids[u]
    size = [1] * n
    for u in range(n - 1, -1, -1):
        if left[u] != -1:
            size[u] += size[left[u]]
        if right[u] != -1:
            size[u] += size[right[u]]
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv = [pow(f, MOD - 2, MOD) for f in fact]
    ways = 1
    for u in range(n):
        a = size[left[u]] if left[u] != -1 else 0
        b = size[u] - 1 - a
        ways = ways * fact[a + b] % MOD * inv[a] % MOD * inv[b] % MOD
    return (ways - 1) % MOD

class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def reverseKGroup(nums, k):
    dummy = ListNode(0, build(nums))
    group_prev = dummy
    while True:
        kth = group_prev
        for _ in range(k):
            kth = kth.next
            if kth is None:
                return dump(dummy.next)
        group_next = kth.next
        prev, cur = group_next, group_prev.next
        while cur is not group_next:
            nxt = cur.next
            cur.next = prev
            prev = cur
            cur = nxt
        old_first = group_prev.next
        group_prev.next = kth
        group_prev = old_first

