def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def mergeKLists(lists):
    heap = []
    for i, vals in enumerate(lists):
        node = build(vals)
        if node:
            heap.append((node.val, i, node))
    heapq.heapify(heap)
    dummy = ListNode()
    tail = dummy
    while heap:
        _, i, node = heapq.heappop(heap)
        tail.next = node
        tail = node
        if node.next:
            heapq.heappush(heap, (node.next.val, i, node.next))
    out = []
    cur = dummy.next
    while cur:
        out.append(cur.val)
        cur = cur.next
    return out

def countFullWalks(grid):
    m, n = len(grid), len(grid[0])
    free = 0
    sr = sc = 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] != -1:
                free += 1
            if grid[r][c] == 1:
                sr, sc = r, c
    seen = [[False] * n for _ in range(m)]

    def go(r, c, left):
        # left = cells not yet visited after standing on (r, c)
        if grid[r][c] == 2:
            return 1 if left == 0 else 0
        seen[r][c] = True
        total = 0
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] != -1 and not seen[nr][nc]:
                total += go(nr, nc, left - 1)
        seen[r][c] = False
        return total

    return go(sr, sc, free - 1)

def countExpressions(num, target):
    n = len(num)

    def go(i, total, last):
        if i == n:
            return 1 if total == target else 0
        cnt = 0
        for j in range(i, n):
            if j > i and num[i] == "0":
                break
            v = int(num[i:j + 1])
            if i == 0:
                cnt += go(j + 1, v, v)
            else:
                cnt += go(j + 1, total + v, v)
                cnt += go(j + 1, total - v, -v)
                cnt += go(j + 1, total - last + last * v, last * v)
        return cnt

    return go(0, 0, 0)

import heapq


def scheduleCourse(courses):
    total = 0
    heap = []
    for duration, last in sorted(courses, key=lambda c: c[1]):
        total += duration
        heapq.heappush(heap, -duration)
        if total > last:
            total += heapq.heappop(heap)
    return len(heap)

import heapq


def runningMediansDoubled(nums):
    lo = []  # max-heap of the smaller half, stored negated
    hi = []  # min-heap of the larger half
    out = []
    for x in nums:
        if not lo or x <= -lo[0]:
            heapq.heappush(lo, -x)
        else:
            heapq.heappush(hi, x)
        if len(lo) > len(hi) + 1:
            heapq.heappush(hi, -heapq.heappop(lo))
        elif len(hi) > len(lo):
            heapq.heappush(lo, -heapq.heappop(hi))
        if len(lo) > len(hi):
            out.append(-2 * lo[0])
        else:
            out.append(-lo[0] + hi[0])
    return out

def countDigitOne(n):
    total = 0
    m = 1
    while m <= n:
        high = n // (m * 10)
        cur = (n // m) % 10
        low = n % m
        if cur == 0:
            total += high * m
        elif cur == 1:
            total += high * m + low + 1
        else:
            total += (high + 1) * m
        m *= 10
    return total

def binomialModPrime(n, r, p):
    fact = [1] * p
    for i in range(1, p):
        fact[i] = fact[i - 1] * i % p

    def small(a, b):
        if b > a:
            return 0
        return fact[a] * pow(fact[b] * fact[a - b] % p, p - 2, p) % p

    result = 1
    while n or r:
        result = result * small(n % p, r % p) % p
        if result == 0:
            return 0
        n //= p
        r //= p
    return result

def countXorPairs(nums, low, high):
    B = 15
    child = [[-1, -1]]
    cnt = [0]
    total_hi = 0
    total_lo = 0
    X_hi = high + 1
    X_lo = low
    for a in nums:
        for X in (X_hi, X_lo):
            node = 0
            res = 0
            for b in range(B - 1, -1, -1):
                ab = (a >> b) & 1
                if (X >> b) & 1:
                    c = child[node][ab]
                    if c != -1:
                        res += cnt[c]
                    node = child[node][ab ^ 1]
                else:
                    node = child[node][ab]
                if node == -1:
                    break
            if X is X_hi:
                total_hi += res
            else:
                total_lo += res
        node = 0
        for b in range(B - 1, -1, -1):
            ab = (a >> b) & 1
            if child[node][ab] == -1:
                child.append([-1, -1])
                cnt.append(0)
                child[node][ab] = len(child) - 1
            node = child[node][ab]
            cnt[node] += 1
    return total_hi - total_lo

from bisect import bisect_left, insort


def maxSumSubmatrix(matrix, k):
    m, n = len(matrix), len(matrix[0])
    if m > n:
        matrix = [list(col) for col in zip(*matrix)]
        m, n = n, m
    best = None
    for top in range(m):
        col = [0] * n
        for bottom in range(top, m):
            row = matrix[bottom]
            for j in range(n):
                col[j] += row[j]
            pre = [0]
            cur = 0
            for x in col:
                cur += x
                idx = bisect_left(pre, cur - k)
                if idx < len(pre):
                    s = cur - pre[idx]
                    if best is None or s > best:
                        best = s
                        if best == k:
                            return best
                insort(pre, cur)
    return best
